        for (int f = 0; f < N; f++) {
            long long score = a[f] + base;
            if (a[f] >= b[f]) score -= (a[f] - b[f]);
            score += sum_u - u[f];
            ans = max(ans, score);
        }
    } else {
        int kk = K;
        long long topK = 0;
        for (int i = 0; i < kk; i++) {
            topK += sorted_u[i].first;
        }
        long long nextVal = sorted_u[kk].first;

        for (int f = 0; f < N; f++) {
            long long score = a[f] + base;
            if (a[f] >= b[f]) score -= (a[f] - b[f]);

            if (rank[f] < kk) {
                score += topK - u[f] + nextVal;
            } else {
                score += topK;
            }

            ans = max(ans, score);
        }
    }

    cout << ans << '\n';
    return 0;
}
